function __af330(t,side,R){/* pkgAFF (ASK 330, ruling 460): the assumed-fact form. Code checks only text: STEP is a quote found in the counted side's own rounds; ROWS GIVE quotes stand in the words of the verses they name (Cited Verses rows); ASSUMES is the judge's own words and must name a given fact, never an inferred act and never contested conclusions or links. Whether the side laid out a chain to that fact is left to the judge's reading. Any check that cannot be made fails (today's handling). */
 try{const s=String(t==null?'':t).replace(/\\+"/g,'"').replace(/\*\*|__|[*`]/g,'');
 const Q=x=>String(x==null?'':x).toLowerCase().replace(/[“”]/g,'"').replace(/[‘’]/g,"'").replace(/[—–]/g,'-').replace(/["']/g,'').replace(/\s+/g,' ').trim();
 const F=x=>String(x==null?'':x).replace(/\[[^\]]*:[^\]]*\]/g,' ').toLowerCase().replace(/[^a-z ]/g,' ').replace(/\s+/g,' ').trim();
 const mS=s.match(/\bSTEP\s*:\s*["“]([^"”]{4,}?)["”]/i);if(!mS)return {ok:false,why:'no STEP quote'};
 const iR=s.search(/\bROWS\s+GIVE\b\s*:?/i);let iA=-1;for(const m of s.matchAll(/\bASSUMES\b/gi)){if(iR<0||m.index<iR)iA=m.index;}if(iA<0)return {ok:false,why:'no ASSUMES'};if(iR<0||iR<iA)return {ok:false,why:'no ROWS GIVE after ASSUMES'};
 const asm=s.slice(iA,iR).replace(/^ASSUMES\s*:?/i,'').split(/\s(?:--|\u2014|\u2013)\s/)[0].replace(/(?:\s*(?:--|—|–|;|,))+\s*$/,'').trim();if(!asm)return {ok:false,why:'the ASSUMES is empty'};
 if(/\b(?:knew|knows?|knoweth|known|knowing|begat|begot|begets?|begotten|begetting|conceived?|conceives|conceiving)\b(?!\s*(?:of|that|as)\b)/i.test(asm))return {ok:false,why:'the ASSUMES names an inferred act'};
 if(/\bcontested\b|\bconclusions?\s+of\s+(?:the\s+)?(?:links?|premises?)\b|\blinks?\s+\d/i.test(asm))return {ok:false,why:'the ASSUMES names contested conclusions or links'};
 let RD=R;if(!RD||typeof RD!=='object'){RD=null;try{const J=($('Panel Build').first().json.judges||[]).find(q=>q&&q.body);const parts=[];const add=c=>{if(typeof c==='string')parts.push(c);else if(Array.isArray(c))c.forEach(p=>{if(p&&typeof p.text==='string')parts.push(p.text);});};((J&&J.body.messages)||[]).forEach(m=>{if(m&&m.role!=='assistant')add(m.content);});const tx=parts.join('\n');const re=/^(?:===[ \t]+)?\[(CR[1-4]|DR[1-4])(?:\]|[ \t]--[^\n]*\])(?:[^\n]*===)?[ \t]*$/gm;const at=[];let m;while((m=re.exec(tx)))at.push({k:m[1],s:m.index,e:m.index+m[0].length});const o={};at.forEach((x,i)=>{if(o[x.k]==null)o[x.k]=tx.slice(x.e,i+1<at.length?at[i+1].s:tx.length);});if(Object.keys(o).length)RD=o;}catch(e){RD=null;}}
 if(!RD)return {ok:false,why:'the rounds could not be read'};
 const own=(side==='CHALLENGER'?['DR1','DR2','DR3','DR4']:['CR1','CR2','CR3','CR4']).map(k=>RD[k]).filter(x=>typeof x==='string').join('\n');
 const ps=String(mS[1]).split(/\.{3}|…/).map(x=>Q(x).replace(/^[\s.,;:!?-]+|[\s.,;:!?-]+$/g,'')).filter(Boolean);const OW=Q(own);
 if(!ps.length||ps.join(' ').split(' ').length<3||!ps.every(p=>OW.includes(p)))return {ok:false,why:'the STEP quote is not found in the '+String(side||'').toLowerCase()+'\'s own rounds'};
 let VR=[];try{VR=$('Cited Verses').all().map(i=>i.json).filter(r=>r&&r.book);}catch(e){VR=[];}const idx={};VR.forEach(r=>{idx[r.book+'|'+r.chapter+'|'+r.verse]=r.text;});
 const rg=s.slice(iR).replace(/^ROWS\s+GIVE\s*:?/i,'');const REF=/((?:[1-3] )?[A-Z][a-z]+(?: of [A-Z][a-z]+)?) (\d{1,3}):(\d{1,3})(?:\s*[-–]\s*(\d{1,3}))?/g;const QR=/["“]([^"”]{3,})["”]/g;
 const ev=[];for(const m of rg.matchAll(REF))ev.push({at:m.index,ref:{b:m[1],c:+m[2],v1:+m[3],v2:+(m[4]||m[3])}});for(const m of rg.matchAll(QR))ev.push({at:m.index,end:m.index+m[0].length,q:m[1]});ev.sort((a,b)=>a.at-b.at);
 let cur=null;const rows=[];for(let i=0;i<ev.length;i++){const e=ev[i];if(e.ref){cur=e.ref;continue;}const nx=ev[i+1];const aft=nx&&nx.ref&&/^[\s(,]{0,6}$/.test(rg.slice(e.end,nx.at))?nx.ref:null;rows.push({ref:aft||cur,q:e.q});}
 if(!rows.length)return {ok:false,why:'the ROWS GIVE quotes no verse words'};
 for(const r of rows){if(!r.ref)return {ok:false,why:'a ROWS GIVE quote names no verse'};const parts=[];for(let v=r.ref.v1;v<=r.ref.v2;v++){const x=idx[r.ref.b+'|'+r.ref.c+'|'+v];if(!x)return {ok:false,why:'the verse '+r.ref.b+' '+r.ref.c+':'+v+' was not read this run'};parts.push(x);}
  const cv=' '+F(parts.join(' '))+' ';const sg=String(r.q).split(/\.{3}|…/).map(F).filter(Boolean);if(!sg.length)return {ok:false,why:'an empty ROWS GIVE quote'};let at=0;for(const g of sg){const k=cv.indexOf(' '+g+' ',at);if(k<0)return {ok:false,why:'the ROWS GIVE quote "'+String(r.q).slice(0,80)+'" is not in the words of '+r.ref.b+' '+r.ref.c+':'+r.ref.v1+(r.ref.v2!==r.ref.v1?'-'+r.ref.v2:'')};at=k+g.length+1;}}
 return {ok:true,why:'STEP found in the side\'s own rounds; ROWS GIVE quotes found in the cited verses; ASSUMES names a given fact',asm,step:mS[1],rows:rows.map(r=>r.ref.b+' '+r.ref.c+':'+r.ref.v1+(r.ref.v2!==r.ref.v1?'-'+r.ref.v2:''))};
 }catch(e){return {ok:false,why:'form reading error: '+String(e&&e.message||e).slice(0,120)};}}
